<script setup name="OperationsReports">
import { ref, reactive, computed, onMounted } from 'vue'
import request from '@/utils/request'
import { ElMessage, ElMessageBox } from 'element-plus'
import { saveAs } from 'file-saver'
import ReportReminders from './components/ReportReminders.vue'
import DailyCorrection from './components/DailyCorrection.vue'
import DailyForms from './components/DailyForms.vue'
import ReportViewers from './components/ReportViewers.vue'
import { checkPermi } from '@/utils/permission'
const base='/kangaroo/operations', chinaDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const today=chinaDate(), filters=reactive({month:today.slice(0,7),cityId:null,roleCode:'',ownerId:null,status:''}),dates=ref([today.slice(0,7)+'-01',today]),active=ref('daily'),page=ref(1),total=ref(0),rows=ref([]),loading=ref(false),saving=ref(false),error=ref(''),options=reactive({cities:[],metrics:[],templatesAllowed:false}),owners=ref([]),targetOwners=ref([]),stores=ref([])
const targetOpen=ref(false),target=ref({}),copyOpen=ref(false),copy=reactive({sourceMonth:filters.month,monthKey:filters.month,cityIds:[]}),resultOpen=ref(false),result=ref({}),detailOpen=ref(false),detail=ref(null),detailKind=ref('daily')
const canGrantViewer=computed(()=>checkPermi(['kangaroo:operations:viewer']))
const issueSummary=ref(null),correctionOpen=ref(false),correctionId=ref(null),correctionHistory=ref(false),dailyForms=ref(null)
const detailManualLabels=computed(()=>detail.value?.form?.fields?[...detail.value.form.fields.filter(f=>f.enabled),{key:'offlineIncome',label:'线下收入（元）'}]:manualLabels)
function editDaily(id,history=false){correctionId.value=id;correctionHistory.value=history;correctionOpen.value=true}
async function corrected(row){if(detailOpen.value&&detailKind.value==='daily'&&detail.value?.reportId===row.reportId)detail.value=row;await load()}
async function beforeTabLeave(next,old){return old==='forms'?await dailyForms.value?.canLeave():true}
let seq=0
const api=(path,method='get',data)=>request({url:base+path,method,...(method==='get'?{params:data}:{data})})
const roleLabel=r=>r==='keeper'?'小院主理人':'换工主理人',rowKey=row=>row.reportId||row.targetId||row.summaryId||row.caseId||row.resultId,progressColor=s=>s==='severe'?'#b8674b':s==='slow'?'#bd9247':'#5a8352'
const availableMetrics=computed(()=>options.metrics.filter(m=>m.roleCode==='both'||m.roleCode===target.value.roleCode)),metricSource=computed(()=>options.metrics.find(m=>m.code===target.value.metricCode)?.source||'')
const summarySections=[{key:'strengths',title:'做得好的地方'},{key:'gaps',title:'差距'},{key:'suggestions',title:'下月建议'}]
const manualLabels=[{key:'tomorrowPlan',label:'明日重点'},{key:'agreedShops',label:'约定店铺及事项'},{key:'issues',label:'今日问题'},{key:'facilities',label:'设施故障'},{key:'shortages',label:'物料缺货'},{key:'yesterdayIssues',label:'昨日问题／特殊情况'},{key:'activityPlan',label:'未来两天活动计划'},{key:'activityNote',label:'活动备注'},{key:'offlineIncome',label:'线下收入（元）'}]
const monthlyCounts=computed(()=>{const c=detail.value?.summary?.counts||{};return [...options.metrics.filter(m=>Object.hasOwn(c,m.code)).map(m=>({label:m.label,value:c[m.code]??'不适用',unit:m.unit})),...['cases','closedCases','openCases'].map((k,i)=>({label:['新增异常','已闭环异常','未闭环异常'][i],value:c[k]??0,unit:'起'}))]})
const taskName=id=>detail.value?.progress?.find(p=>String(p.targetId)===String(id))?.label||'目标'+id
function params(){return {...filters,pageNum:page.value,dateFrom:dates.value?.[0],dateTo:dates.value?.[1]}}
async function load(){if(!filters.month)return ElMessage.warning('请选择月份');const n=++seq;loading.value=true;error.value='';try{if(active.value==='results'&&!filters.cityId){rows.value=[];return}const r=await api('/'+active.value,'get',params());if(n!==seq)return;rows.value=Array.isArray(r.data)?r.data:r.data.rows||[];total.value=r.data.total||0;issueSummary.value=r.data.summary||null}catch(e){if(n===seq)error.value=e.message||'加载失败，请重试'}finally{if(n===seq)loading.value=false}}
async function scopeChanged(){filters.ownerId=null;owners.value=[];if(filters.cityId&&filters.roleCode){try{owners.value=(await api('/owners','get',filters)).data}catch{}}}
function tabChanged(){seq++;loading.value=false;error.value='';if(['reminders','forms','viewers'].includes(active.value))return;filters.status='';if(active.value==='daily'&&filters.ownerId===0)filters.ownerId=null;if(active.value!=='targets'&&filters.cityId===0)filters.cityId=null;page.value=1;load()}
async function targetScope(){target.value.ownerId=0;targetOwners.value=[];if(target.value.cityId&&target.value.roleCode)targetOwners.value=(await api('/owners','get',target.value)).data;if(!availableMetrics.value.some(m=>m.code===target.value.metricCode))target.value.metricCode=availableMetrics.value[0]?.code}
async function editTarget(row){target.value=row?{...row}:{monthKey:filters.month,cityId:filters.cityId??options.cities[0]?.cityId,roleCode:filters.roleCode||'keeper',ownerId:filters.ownerId||0,metricCode:'activities',targetValue:1,normalRatio:80,slowRatio:50};targetOwners.value=[];if(!row&&!availableMetrics.value.some(m=>m.code===target.value.metricCode))target.value.metricCode=availableMetrics.value[0]?.code;if(target.value.cityId)targetOwners.value=(await api('/owners','get',target.value)).data;targetOpen.value=true}
async function mutate(fn){if(saving.value)return;saving.value=true;try{await fn();await load()}catch(e){ElMessage.error(e.message||'保存失败')}finally{saving.value=false}}
async function saveTarget(){if(!target.value.monthKey||target.value.cityId==null||!target.value.metricCode)return ElMessage.warning('请填写月份、城市和指标');await mutate(async()=>{await api('/targets','post',target.value);targetOpen.value=false;ElMessage.success('目标已保存')})}
async function copyTargets(){await mutate(async()=>{const r=await api('/targets/copy','post',copy);copyOpen.value=false;ElMessage.success('已新增 '+r.data+' 项目标，原目标已保留')})}
async function generate(){if(!filters.cityId||!filters.roleCode)return ElMessage.warning('请先选择具体城市和身份');await mutate(async()=>{await api('/monthly','post',{monthKey:filters.month,cityId:filters.cityId,roleCode:filters.roleCode,ownerId:filters.ownerId||0});ElMessage.success('总结已生成或返回原有总结')})}
async function send(row){try{await ElMessageBox.confirm('发送给该主理人；地区团队总结发送给有完整范围权限的城市负责人。重复发送不会重复提醒。','发送月度总结',{type:'info'});const r=await api('/monthly/'+row.summaryId+'/send','post',{});ElMessage.success(r.data.sent?'已发送 '+r.data.sent+' 条提醒':'没有新增提醒，可能已发送或暂无有效接收人')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'发送失败')}}
async function editResult(row){if(!filters.cityId)return ElMessage.warning('请先选择具体城市');stores.value=(await api('/stores','get',{cityId:filters.cityId})).data;result.value=row?{...row,occurredDate:row.occurredAt.slice(0,10)}:{metricCode:'managedContracts',occurredDate:today,status:'0',evidence:''};resultOpen.value=true}
async function saveResult(){await mutate(async()=>{await api('/results','post',result.value);resultOpen.value=false;ElMessage.success('实际结果已登记')})}
async function showReport(kind,id){try{detail.value=(await api('/'+kind+'/'+id)).data;detailKind.value=kind;detailOpen.value=true}catch(e){ElMessage.error(e.message||'无法读取报表')}}
async function download(path,format,query={}){try{const data=await request({url:base+path,method:'get',params:{...query,format},responseType:'blob'});const blob=data instanceof Blob?data:new Blob([data]);if(blob.type.includes('json')){const failure=JSON.parse(await blob.text());throw new Error(failure.msg||'导出失败')}saveAs(blob,'袋鼠工作报表.'+format)}catch(e){ElMessage.error(e.message||'导出失败')}}
const exportDetail=format=>detail.value&&download('/export/'+detailKind.value+'/'+(detail.value.reportId||detail.value.summaryId),format)
const exportBoard=format=>download('/export/targets',format,params())
const exportList=format=>download('/export-batch/'+active.value,format,params())
onMounted(async()=>{try{Object.assign(options,(await api('/options')).data);await load()}catch(e){error.value=e.message||'初始化失败'}})
</script>
<style scoped>
.operations{max-width:1600px}.page-head{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}.page-head h2{font-size:24px;margin:0 0 10px;color:#303a35}.page-head p{color:#727972;font-size:14px;margin:0}.filters{padding:18px 18px 0;background:#f7f8f6;border:1px solid #e5e9e1;border-radius:8px}.toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:8px 0 18px}.toolbar .el-button+.el-button{margin-left:0}.help{font-size:12px;color:#787f77;line-height:1.6}.block{display:block;width:100%;margin-top:6px}.pagination{justify-content:flex-end;margin-top:20px}.gap{margin-bottom:16px}.report-meta{display:flex;flex-direction:column;gap:8px;margin-bottom:20px;color:#727972}.report-meta strong{font-size:19px;color:#303a35}.pre,dd{white-space:pre-wrap;word-break:break-word;line-height:1.8}dl{display:grid;grid-template-columns:150px 1fr;gap:12px}dt{font-weight:600}dd{margin:0}h3{font-size:17px;margin-top:28px}h4{font-size:15px}@media(max-width:768px){.page-head{align-items:flex-start;flex-direction:column}.filters{padding:12px}.toolbar{gap:10px}dl{grid-template-columns:1fr;gap:7px}dd{margin-bottom:10px}}
</style>
